    private static void feature(MainActivity a,LinearLayout host,ArtworkLoader loader,Song song,String label,String subtitle,int color,int width,Runnable action){
        LinearLayout card=a.col();card.setPadding(a.dp(20),a.dp(20),a.dp(20),a.dp(18));GradientDrawable bg=new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{color,color});bg.setCornerRadius(a.dp(20));card.setBackground(bg);
        LinearLayout upper=a.row();TextView labelView=a.text(label,20,Color.WHITE);labelView.setTypeface(null,android.graphics.Typeface.BOLD);upper.addView(labelView,new LinearLayout.LayoutParams(0,-1,1));upper.addView(cover(a,loader,song,76));card.addView(upper,new LinearLayout.LayoutParams(-1,0,1));a.gap(card,20);TextView caption=a.text(subtitle,15,0xfff0f3f5);caption.setSingleLine();caption.setEllipsize(android.text.TextUtils.TruncateAt.END);card.addView(caption);card.setOnClickListener(v->action.run());LinearLayout.LayoutParams params=a.lp(width,166);params.rightMargin=a.dp(14);host.addView(card,params);
    }
